func (q *Queries) TouchContainerSession(ctx context.Context, arg TouchContainerSessionParams) error {
	_, err := q.db.Exec(ctx, touchContainerSession, arg.ActivityAt, arg.ID, arg.WorkspaceID)
	return err
}

const updateContractReview = `-- name: UpdateContractReview :one
UPDATE contract_review SET fields = $1, status = $2, result = $3, note = $4,
    version = version + 1, last_actor_id = $5, updated_at = clock_timestamp(),
    creator_read_version = CASE WHEN creator_id = $5 THEN version + 1 ELSE creator_read_version END,
    peer_read_version = CASE WHEN creator_id <> $5 THEN version + 1 ELSE peer_read_version END
WHERE id = $6 AND workspace_id = $7 AND version = $8
RETURNING id, workspace_id, creator_id, fields, status, result, note, version, creator_read_version, peer_read_version, last_actor_id, submission_hash, created_at, updated_at, application_id, application_version, application_snapshot
`

type UpdateContractReviewParams struct {
	Fields          []byte      `json:"fields"`
	Status          string      `json:"status"`
	Result          string      `json:"result"`
	Note            string      `json:"note"`
	ActorID         pgtype.UUID `json:"actor_id"`
	ID              pgtype.UUID `json:"id"`
	WorkspaceID     pgtype.UUID `json:"workspace_id"`
	ExpectedVersion int32       `json:"expected_version"`
}

func (q *Queries) UpdateContractReview(ctx context.Context, arg UpdateContractReviewParams) (ContractReview, error) {
	row := q.db.QueryRow(ctx, updateContractReview,
		arg.Fields,
		arg.Status,
		arg.Result,
		arg.Note,
		arg.ActorID,
		arg.ID,
		arg.WorkspaceID,
		arg.ExpectedVersion,
	)
	var i ContractReview
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.CreatorID,
		&i.Fields,
		&i.Status,
		&i.Result,
		&i.Note,
		&i.Version,
		&i.CreatorReadVersion,
		&i.PeerReadVersion,
		&i.LastActorID,
		&i.SubmissionHash,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.ApplicationID,
		&i.ApplicationVersion,
		&i.ApplicationSnapshot,
	)
	return i, err
}
